        target_words / n_sentences / vocabulary. Values are the
        corresponding lists of processed sentences, or an error string
        ('Error: ...') if that set could not be processed (e.g. negative
        n_sentences or an empty vocabulary).
    """

    def process_set(target_words, n_sentences, vocabulary):
        if n_sentences < 0:
            raise ValueError("n_sentences must be a positive integer")
        if not vocabulary:
            raise ValueError("vocabulary must not be empty")

        sentences = []
        for _ in range(n_sentences):
            # Each sentence consists of 10 randomly sampled words.
            if len(vocabulary) >= 10:
                words = random.sample(list(vocabulary), 10)
            else:
                # If the vocabulary is smaller than 10 words, sample
                # with replacement so a full sentence can still be built.
                words = [random.choice(list(vocabulary)) for _ in range(10)]
            sentence = " ".join(words)

            # If any target word appears in the sentence, replace the
            # spaces within that word with underscores.
            for tw in target_words:
                if tw in sentence:
                    sentence = sentence.replace(tw, tw.replace(" ", "_"))

            sentences.append(sentence)
        return sentences

    report = {}
    for idx, item in enumerate(data):
